window.SDT_NOTES=window.SDT_NOTES||{};window.SDT_NOTES["4"]={"week":"4","title":"4강. 목공사","units":[{"id":"w4-1","title":"목재의 장단점과 조직","goal":"목재의 두 가지 쓰임과 장단점, 통나무 단면의 수심, 심재, 변재, 수피를 말할 수 있어요","terms":[{"ko":"구조적 측면","en":"","say":"벽체, 칸막이 속처럼 노출되지 않는 기본 틀을 만드는 목재의 쓰임","more":"짝은 치장적 측면. 요즘 구조공사의 목재 비중은 줄고 마감, 가구공사 비중이 커짐."},{"ko":"치장적 측면","en":"","say":"걸레받이, 창호, 바닥, 계단, 핸드레일, 가구처럼 목재 자체가 노출되는 쓰임","more":"마감 성격. 짝은 구조적 측면."},{"ko":"비중","en":"","say":"같은 부피의 물과 비교해 그 물질이 얼마나 무거운지 나타내는 값","more":"목재 비중 = 나무 밀도 / 물 밀도. 침엽수 0.3~0.5, 활엽수 0.5~0.9. 클수록 강도는 오르고 수축, 뒤틀림도 커짐."},{"ko":"수심","en":"Pith","say":"나무 줄기의 한가운데 중심","more":"횡단면 3부분 : 수심, 목질부, 수피."},{"ko":"수피","en":"Bark","say":"나무의 껍질 부분","more":"수분과 영양을 섭취. 오래된 나무일수록 껍질이 두꺼움."},{"ko":"나이테","en":"Growth ring","say":"1년에 한 줄씩 생기는 고리 모양 부분, 연륜이라고도 함","more":"춘재와 추재가 반복되며 형성."},{"ko":"춘재","en":"Earlywood","say":"봄에 자라 세포가 크고 면적이 넓은 나이테 부분","more":"물 공급 충분, 세포분열 활발, 물관 발달. 짝은 추재."},{"ko":"추재","en":"Latewood","say":"한여름부터 느리게 자라 세포벽이 두껍고 치밀한 부분","more":"하재라고도 함. 짝은 춘재."},{"ko":"심재","en":"Heartwood","say":"수심 가까이 짙은 색의, 수액 전달을 멈춘 단단한 속 부분","more":"수분 적고 변형 거의 없음, 강도와 내구성 큼, 깎으면 광택. 오크, 월넛, 체리는 주로 심재를 씀."},{"ko":"변재","en":"Sapwood","say":"표피 가까이 옅은 색의, 수액을 나르는 살아 있는 바깥 부분","more":"함수율 높고 무름, 켠 뒤에도 변형, 균열. 수축률이 심재보다 큼. 메이플, 자작, 애쉬는 변재도 많이 씀."}],"slides":[{"kind":"title","big":"나무의 두 얼굴과 속살","sub":"목공사는 경량철골과 같은 일을 나무로도 해요"},{"kind":"goal","items":["목재의 쓰임을 구조적 측면과 치장적 측면으로 나눠요","목재의 장점과 단점을 목록으로 말해요","통나무 단면에서 수심, 심재, 변재, 수피를 구별해요"]},{"kind":"analogy","head":"두 얼굴의 배우","scene":"같은 배우가 무대 뒤에서는 스태프로, 무대 위에서는 주인공으로 일해요.","map":[["무대 뒤 스태프","**구조적 측면**"],["무대 위 주인공","**치장적 측면**"],["요즘 늘어난 출연","마감공사와 가구공사"]]},{"kind":"points","head":"공사 순서 속 목공사","items":["현장 작업 순서는 가설 → 철거 → 경량철골 → 마감 예요","3강의 **메탈 스터드(Metal Stud)** 가 하던 틀 짜기를 나무로도 해요","목공사는 벽, 천장의 틀과 마감의 바탕을 만드는 자리에 와요"]},{"kind":"compare","head":"목재의 두 얼굴","cols":["쓰임","어디에"],"rows":[["**구조적 측면**","벽체나 칸막이 속처럼 노출되지 않는 기본 틀"],["**치장적 측면**","걸레받이, 창호, 바닥, 계단, 핸드레일, 가구"]]},{"kind":"points","head":"구조공사 비중이 줄어든 까닭","items":["금속재와 경량 철골 시스템이 구조재 역할을 대신하게 됐어요","그래서 **구조적 측면** 에서 목재 비중은 줄고 있어요","대신 **치장적 측면** 의 마감공사, 가구공사 비중이 높아져요","벽도 요즘은 **건식벽체(Dry-Wall)** 처럼 철 뼈대가 기본이에요"]},{"kind":"points","head":"장점 (1) 가볍고 따뜻해요","items":["**비중** 은 같은 부피의 물과 비교한 무게예요","**비중** 이 작아 가볍고, 무게에 비해 강도가 커요","가공성과 시공성이 우수하고, 열과 전기를 잘 전도하지 않아요","열전도율이 낮아 보온성, 방한성이 우수해요"]},{"kind":"points","head":"장점 (2) 예쁘고 친환경이에요","items":["외관이 미려하여 마감재와 가구재로 우수해요","재활용이 가능하고, 탄소발생율이 적고, 자연에서 분해돼요","접착제, 맞춤, 하드웨어로 쉽게 접합해요","소리의 흡수, 차단성과 충격, 진동 흡수 능력이 좋아요"]},{"kind":"points","head":"단점 다섯 가지","items":["불에 타기 쉽고 습기에 약해요","비내구적이며 부식성이 커요","건조하면서 뒤틀리거나 갈라지기 쉬워요","옹이, 썩음, 송진구멍 같은 조직적 결함이 있어요","매우 크고 긴 재료를 얻기 힘들어요"]},{"kind":"figure","head":"통나무를 자르면","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"130.0\" cy=\"140.0\" r=\"115\" class=\"n b1\"/><circle cx=\"130.0\" cy=\"140.0\" r=\"98\" class=\"n3 b2\"/><circle cx=\"130.0\" cy=\"140.0\" r=\"58\" class=\"n2 b3\"/><circle cx=\"130.0\" cy=\"140.0\" r=\"6\" class=\"n4 b4\"/><line x1=\"212.0\" y1=\"58.0\" x2=\"272.0\" y2=\"38.0\" class=\"e b1\"/><text x=\"280.0\" y=\"44.0\" font-size=\"15\" text-anchor=\"start\" class=\"tb b1\">수피 (껍질)<\/text><line x1=\"195.0\" y1=\"86.0\" x2=\"272.0\" y2=\"92.0\" class=\"e b2\"/><text x=\"280.0\" y=\"98.0\" font-size=\"15\" text-anchor=\"start\" class=\"tb b2\">변재 (옅고 무름)<\/text><line x1=\"160.0\" y1=\"135.0\" x2=\"272.0\" y2=\"148.0\" class=\"e b3\"/><text x=\"280.0\" y=\"154.0\" font-size=\"15\" text-anchor=\"start\" class=\"tb b3\">심재 (짙고 단단)<\/text><line x1=\"136.0\" y1=\"142.0\" x2=\"272.0\" y2=\"202.0\" class=\"e b4\"/><text x=\"280.0\" y=\"208.0\" font-size=\"15\" text-anchor=\"start\" class=\"tb b4\">수심 (중심)<\/text><\/svg>","caption":"바깥부터 수피, 변재, 심재, 가운데 수심이에요. 나이테가 그 사이에 겹겹이 있어요.","builds":4},{"kind":"points","head":"횡단면 3부분","items":["목재의 횡단면은 **수심(Pith)**, 목질부, **수피(Bark)** 의 3부분이에요","**수심(Pith)** 은 나무의 중심이에요","**수피(Bark)** 는 껍질이고 수분과 영양을 섭취해요, 오래된 나무일수록 두꺼워요"]},{"kind":"compare","head":"**나이테(Growth ring)** 를 만드는 두 층","cols":["층","특징"],"rows":[["**춘재(Earlywood)**","물이 충분해 세포분열이 활발, 세포가 크고 면적이 넓어요"],["**추재(Latewood)**","한여름부터 느리게 자라 세포벽이 두껍고 치밀해요, 하재라고도 해요"],["**나이테(Growth ring)**","**춘재(Earlywood)** 와 **추재(Latewood)** 가 반복되며 1년에 한 줄씩 생겨요"]]},{"kind":"compare","head":"속살과 바깥살","cols":["부분","특징"],"rows":[["**심재(Heartwood)**","수심 가까이, 성장이 거의 멈춘 조직, 수분이 적어 변형이 거의 없어요"],["**심재(Heartwood)**","강도와 내구성이 크고 깎으면 광택이 있어요"],["**변재(Sapwood)**","표피 가까이, 수액과 양분을 나르고 함수율이 높아 물러요"],["**변재(Sapwood)**","켠 뒤에도 변형과 균열이 생길 수 있어요"]]},{"kind":"points","head":"수종마다 쓰는 부분","items":["오크, 월넛, 체리는 **심재(Heartwood)** 비율이 커서 주로 심재를 써요","메이플, 자작, 애쉬는 밝은 색의 **변재(Sapwood)** 도 많이 써요","변재가 심재로 되면서 추출물이 생겨 나무마다 색과 특성이 달라져요"]},{"kind":"check","q":"수심 가까이에 있고 수분이 적어 변형이 거의 없으며 강도와 내구성이 큰 부분은?","choices":["심재","변재","수피"],"a":0,"why":"심재는 수액 전달을 멈춘 단단한 속살이에요. 변재는 수분이 많아 물러요."},{"kind":"warn","head":"슬라이드 낱말이 뒤바뀐 곳","items":["p4 는 심재를 짙은 담색, 변재를 옅은 암갈색 부분으로 적어요","담색은 옅은 색, 암갈색은 어두운 갈색이라 두 낱말이 서로 바뀐 것으로 보여요","외울 때는 **심재(Heartwood)** 는 짙고 단단, **변재(Sapwood)** 는 옅고 무름으로 잡아요"]},{"kind":"english","head":"답안에 쓸 문장","en":"목재는 가볍고 강하며 보온, 흡음성이 좋지만 불과 습기에 약하고 뒤틀림, 옹이 결함, 크기 제한이 있다.","ko":"장점 하나, 단점 하나씩 번갈아 떠올리며 써요"},{"kind":"recap","items":["**구조적 측면** 은 안 보이는 틀, **치장적 측면** 은 보이는 마감이에요","**비중** 이 작아 가볍고 강하지만 불과 습기에 약해요","횡단면은 **수심(Pith)**, 목질부, **수피(Bark)** 예요","**나이테(Growth ring)** 는 **춘재(Earlywood)** 와 **추재(Latewood)** 가 반복돼 생겨요","**심재(Heartwood)** 는 단단한 속살, **변재(Sapwood)** 는 촉촉한 바깥살이에요","오늘의 용어: 구조적 측면, 치장적 측면, 비중, 수심(Pith), 수피(Bark), 나이테(Growth ring), 춘재(Earlywood), 추재(Latewood), 심재(Heartwood), 변재(Sapwood)"]}]},{"id":"w4-2","title":"목재의 성질: 비중, 함수율, 수축, 강도","goal":"함수율 공식과 표, 예제 38.89%, 수축 방향 순서, 강도 순서와 약한 3가지 강도를 말할 수 있어요","terms":[{"ko":"함수율","en":"","say":"목재가 물을 머금은 정도","more":"낮을수록 강도가 큼. 공식 (건조 전 중량 - 절건 중량) / 절건 중량 × 100. 예제 15kg, 전건 10.8kg이면 38.89%."},{"ko":"섬유포화점","en":"","say":"자유수는 빠지고 세포막 속 흡착수만 남은 함수율 30% 정도의 상태","more":"이상에서는 강도 변화 없음, 이하에서는 마를수록 강도 증가. 자연건조로 수분의 70% 제거된 지점."},{"ko":"자유수","en":"Free water","say":"세포 안 통로(수관, 체관)에 고인 물","more":"흡착수와 약 7:3. 자연건조로 먼저 빠짐."},{"ko":"흡착수","en":"Bound water","say":"세포벽 속에 스며든 물","more":"인공(강제) 건조로 제거. 빠지면 단단해지지만 부피가 줄고 균열."},{"ko":"기건재","en":"","say":"공기 중에서 더 이상 마르지 않는 상태까지 자연 건조된 목재","more":"함수율 15% (10~15%). 대기 중 노출 상태."},{"ko":"전건재","en":"","say":"인공적으로 완전히 말려 함수율이 0%인 목재","more":"절건재라고도 함. 외력으로 강제로 수분 제거. 함수율 표 : 전건재 0, 기건재 15, 섬유포화점 30, 구조재 20(25 이하), 수장재 15(18 이하)."},{"ko":"둘레 방향 수축","en":"Tangential shrinkage","say":"나이테를 따라 도는 방향의 수축, 가장 큼","more":"수직 방향의 1.5~2배. 순서 : 둘레 > 수직 >>> 길이."},{"ko":"인장 강도","en":"Tensile Strength","say":"양쪽으로 잡아당길 때 버티는 힘","more":"결방향이 결수직방향보다 강함. 결수직 인장은 설계 상 회피. 강도 순서 1위."},{"ko":"전단 강도","en":"Shear Strength","say":"단면을 위아래로 엇갈려 끊으려는 힘에 버티는 힘","more":"섬유방향과 수직일 때 더 큼. 강도 순서 : 인장 > 휨 > 압축 > 전단."},{"ko":"결수직방향","en":"","say":"목재 섬유방향과 수직인 방향, 횡단방향","more":"약한 3가지 : 결수직 압축에 의한 변형, 결수직 인장에 의한 파괴, 결방향 전단에 의한 파괴."}],"slides":[{"kind":"title","big":"물과 힘으로 보는 나무","sub":"마를수록 단단해지고, 줄어들고, 방향마다 달라요"},{"kind":"goal","items":["함수율 공식과 표의 숫자를 외우고 예제를 풀어요","수축이 큰 방향과 작은 방향을 말해요","강도 순서와 목재가 약한 3가지 강도를 말해요"]},{"kind":"analogy","head":"젖은 스펀지","scene":"스펀지 구멍에 고인 물은 짜면 금방 빠지고, 스펀지 몸에 밴 물은 오래 말려야 빠져요.","map":[["구멍에 고인 물","**자유수(Free water)**"],["스펀지 몸에 밴 물","**흡착수(Bound water)**"],["구멍 물만 다 빠진 순간","**섬유포화점**"]]},{"kind":"points","head":"**비중** 다시 보기","items":["일반적으로 침엽수는 비중이 낮고 연하며, 활엽수는 0.5~0.9 로 높고 단단해요","비중이 클수록 강도는 향상돼요","하지만 수축이 커지고 뒤틀림의 양도 많아져요","기건 비중은 수분을 공기 중에서 뺀 상태의 비중이에요"]},{"kind":"points","head":"**함수율** 이란","items":["**함수율** 은 목재가 물을 머금은 정도예요","**함수율** 이 낮을수록 강도가 커요","**섬유포화점** 이상에서는 강도 변화가 없어요","**섬유포화점** 이하부터는 마를수록 강도가 증가해요"]},{"kind":"points","head":"나무 속 물 두 가지","items":["**자유수(Free water)** 는 수관, 체관 같은 통로 속 물이에요","**흡착수(Bound water)** 는 세포벽 속에 스며든 물이에요","둘은 약 7:3 비율로 있어요","자연건조로 **자유수(Free water)** 가 빠지면 수분의 70% 가 빠진 **섬유포화점** 이에요"]},{"kind":"compare","head":"함수율 표 (실내건축기사 기준)","cols":["상태","함수율"],"rows":[["**전건재**","0%, 절건재라고도 하고 강제로 수분을 제거한 상태"],["**기건재**","15% (10~15%), 대기 중에 노출된 자연 건조 상태"],["**섬유포화점**","30%"],["구조재","20% (25% 이하)"],["수장재","15% (18% 이하)"]]},{"kind":"figure","head":"함수율 숫자 줄","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"36.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">낮을수록 단단해요, 30% 위에서는 강도가 그대로예요<\/text><line x1=\"40.0\" y1=\"140.0\" x2=\"440.0\" y2=\"140.0\" class=\"e b1\"/><line x1=\"40.0\" y1=\"130.0\" x2=\"40.0\" y2=\"150.0\" class=\"e b1\"/><text x=\"40.0\" y=\"122.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">0%<\/text><text x=\"40.0\" y=\"96.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">전건재<\/text><line x1=\"240.0\" y1=\"130.0\" x2=\"240.0\" y2=\"150.0\" class=\"e b2\"/><text x=\"240.0\" y=\"122.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">15%<\/text><text x=\"240.0\" y=\"96.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">기건재<\/text><text x=\"240.0\" y=\"176.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">수장재 15%<\/text><line x1=\"306.7\" y1=\"130.0\" x2=\"306.7\" y2=\"150.0\" class=\"e b2\"/><text x=\"306.7\" y=\"204.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">구조재 20%<\/text><line x1=\"440.0\" y1=\"130.0\" x2=\"440.0\" y2=\"150.0\" class=\"e b1\"/><text x=\"440.0\" y=\"122.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">30%<\/text><text x=\"440.0\" y=\"96.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">섬유포화점<\/text><text x=\"240.0\" y=\"248.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b3\">(15 - 10.8) / 10.8 × 100 = 38.89%<\/text><\/svg>","caption":"전건재 0, 기건재 15, 수장재 15, 구조재 20, 섬유포화점 30 이에요.","builds":3},{"kind":"steps","head":"예제 풀기 (문제 4, 3점)","steps":["식은 (나무무게 - 전건무게) / 전건무게 × 100 이에요","빼기 먼저, 15 - 10.8 = 4.2 예요","나누기, 4.2 / 10.8 = 0.38888... 이에요","100 을 곱하면 38.888...% 예요","각재 크기와 길이는 계산에 쓰지 않아요"],"answer":"답은 38.89% 예요, 분모는 전건무게예요","given":"10×10cm 각, 길이 6m, 무게 15kg, 전건중량 10.8kg"},{"kind":"compare","head":"수축은 방향마다 달라요","cols":["방향","정도"],"rows":[["**둘레 방향 수축(Tangential shrinkage)**","나이테를 따라 도는 방향, 가장 커요"],["**수직 방향 수축(Radial shrinkage)**","중심에서 바깥으로 가는 반지름 방향, 그다음이에요"],["**종 방향 수축(longitudinal shrinkage)**","나무 길이 방향, 거의 일어나지 않아요"]]},{"kind":"points","head":"수축 순서 외우기","items":["줄기(길이) < 반지름(수직) < 나이테 접선(둘레) 순서로 커져요","**변재(Sapwood)** 가 **심재(Heartwood)** 보다 수축률이 훨씬 커요","수분이 많고 조직이 느슨한 쪽이 더 줄어들어요","주문은 길, 반, 둘 이에요, **둘레 방향 수축(Tangential shrinkage)** 이 최고예요"]},{"kind":"compare","head":"힘 네 가지","cols":["강도","뜻"],"rows":[["**인장 강도(Tensile Strength)**","양쪽으로 잡아당길 때 버티는 힘, 결방향이 강해요"],["**압축 강도(Compressive Strength)**","길이 방향으로 양쪽에서 누를 때 버티는 힘, 대표 부재는 기둥"],["**휨 강도(Bending Strength)**","두께 방향 하중에 버티는 힘, 압축 강도의 약 1.75배"],["**전단 강도(Shear Strength)**","단면을 위아래로 끊으려는 힘에 버티는 힘"]]},{"kind":"points","head":"강도 순서 (정리!)","items":["목재의 강도 순서는 인장 > 휨 > 압축 > 전단, 1등은 **인장 강도(Tensile Strength)** 예요","**인장 강도(Tensile Strength)** 와 압축 강도는 결방향이 강해요","**전단 강도(Shear Strength)** 만 거꾸로 **결수직방향** 이 더 강해요","힘이 결에 경사지게 걸리면 전단강도가 적용돼 매우 약해져요"]},{"kind":"compare","head":"목재가 약한 3가지 강도","cols":["약점","슬라이드 표시"],"rows":[["**결수직방향** 압축에 의한 변형","잠재적 문제, **가압수축(compression shrinkage)**"],["**결수직방향** 인장에 의한 파괴","설계 상 회피, 2% 정도 변형율에서 갑자기 파괴"],["결방향 전단에 의한 파괴","결방향 **전단 강도(Shear Strength)** 가 약해요"]]},{"kind":"check","q":"10×10cm 각, 길이 6m, 무게 15kg, 전건중량 10.8kg 인 나무의 함수율은?","choices":["약 28.00%","약 38.89%","약 72.00%"],"a":1,"why":"(15 - 10.8) / 10.8 × 100 = 38.89% 예요. 분모를 15 로 두면 28.00% 가 나오는 함정이에요."},{"kind":"check","q":"자유수가 빠지고 흡착수만 남은 함수율 30% 정도의 상태는?","choices":["기건재","섬유포화점","전건재"],"a":1,"why":"기건재는 15%, 전건재는 0% 예요."},{"kind":"warn","head":"슬라이드끼리 다른 숫자","items":["수축 배수가 한 줄은 2배, 같은 쪽 상자는 1.5~2배로 적혀 있어요","자유수와 흡착수는 본문 7:3, 그림은 72% 와 28% 로 적혀 있어요","외울 때는 **둘레 방향 수축(Tangential shrinkage)** 이 가장 크다는 순서를 먼저 잡아요"]},{"kind":"recap","items":["**함수율** 은 (건조 전 - 전건) / 전건 × 100, 예제 답은 38.89% 예요","**전건재** 0, **기건재** 15, **섬유포화점** 30, 구조재 20, 수장재 15 예요","**자유수(Free water)** 와 **흡착수(Bound water)** 는 약 7:3 이에요","수축은 길, 반, 둘 순서로 커지고 **변재(Sapwood)** 가 더 줄어요","강도는 인장 > 휨 > 압축 > 전단, **전단 강도(Shear Strength)** 만 **결수직방향** 이 강해요","오늘의 용어: 함수율, 섬유포화점, 자유수(Free water), 흡착수(Bound water), 기건재, 전건재, 둘레 방향 수축(Tangential shrinkage), 인장 강도(Tensile Strength), 전단 강도(Shear Strength), 결수직방향"]}]},{"id":"w4-3","title":"수종에 따른 분류","goal":"침엽수재와 활엽수재의 특징과 대표 수종, 눈에 띄는 수종의 한 가지 특징을 말할 수 있어요","terms":[{"ko":"침엽수재","en":"Softwood","say":"바늘잎 나무의 목재, 소프트 우드","more":"연목. 건조 빠름, 크고 긴 재료. 삼나무, 소나무, 전나무, 잣나무, 낙엽송. 건축재 선호."},{"ko":"활엽수재","en":"Hardwood","say":"넓은잎 나무의 목재, 하드 우드","more":"경목. 건조에 오래 걸림, 다양한 모양. 자작나무, 물푸레나무, 벚나무, 흑단, 너도밤나무, 마호가니, 단풍나무. 가구 선호."},{"ko":"비중","en":"","say":"같은 부피의 물과 비교해 그 물질이 얼마나 무거운지 나타내는 값","more":"목재 비중 = 나무 밀도 / 물 밀도. 침엽수 0.3~0.5, 활엽수 0.5~0.9. 클수록 강도는 오르고 수축, 뒤틀림도 커짐."},{"ko":"심재","en":"Heartwood","say":"수심 가까이 짙은 색의, 수액 전달을 멈춘 단단한 속 부분","more":"수분 적고 변형 거의 없음, 강도와 내구성 큼, 깎으면 광택. 오크, 월넛, 체리는 주로 심재를 씀."},{"ko":"변재","en":"Sapwood","say":"표피 가까이 옅은 색의, 수액을 나르는 살아 있는 바깥 부분","more":"함수율 높고 무름, 켠 뒤에도 변형, 균열. 수축률이 심재보다 큼. 메이플, 자작, 애쉬는 변재도 많이 씀."}],"slides":[{"kind":"title","big":"바늘잎과 넓은잎","sub":"나무 종류로 성질과 쓰임이 갈려요"},{"kind":"goal","items":["침엽수재와 활엽수재의 특징을 비교해요","대표 수종을 각각 말해요","눈에 띄는 수종의 한 가지 특징을 짝지어요"]},{"kind":"analogy","head":"운동선수와 공예가","scene":"키 크고 곧은 선수는 무거운 짐을 나르고, 손재주 좋은 공예가는 섬세한 작품을 만들어요.","map":[["곧고 길게 자라 짐을 나르는 선수","**침엽수재(Softwood)**"],["단단하고 무늬가 고운 공예가","**활엽수재(Hardwood)**"],["짐 나르기와 작품 만들기","건축재 선호와 가구 선호"]]},{"kind":"compare","head":"두 갈래 비교","cols":["구분","침엽수재","활엽수재"],"rows":[["잎","바늘 모양","넓은 모양"],["단단함","비교적 연목","비교적 경목"],["건조","벌목 후 빠름","상당한 시일, 마르면 단단해짐"],["모양","곧게 자라 크고 긴 재료","침엽수보다 다양한 모양"],["선호","건축재","가구"]]},{"kind":"points","head":"**비중** 으로 보면","items":["일반적으로 **침엽수재(Softwood)** 는 **비중** 이 낮고 비교적 연해요","**활엽수재(Hardwood)** 는 **비중** 이 0.5~0.9 로 높고 단단해요","오크, 월넛, 체리는 주로 **심재(Heartwood)**, 메이플은 **변재(Sapwood)** 를 많이 써요"]},{"kind":"points","head":"건조 속도 다시 보기","items":["건조는 4-2 의 **함수율** 을 낮추는 일이에요","자연건조로 자유수가 빠지면 **섬유포화점** 근처까지 내려가요","**침엽수재(Softwood)** 는 벌목 후 건조가 빠르고 **활엽수재(Hardwood)** 는 상당한 시일이 걸려요"]},{"kind":"figure","head":"분류표 그림","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"165\" y=\"16\" width=\"150\" height=\"40\" rx=\"2\" class=\"box b1\"/><text x=\"240.0\" y=\"42.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">종자 식물<\/text><line x1=\"240.0\" y1=\"56.0\" x2=\"120.0\" y2=\"92.0\" class=\"e b2\"/><line x1=\"240.0\" y1=\"56.0\" x2=\"360.0\" y2=\"92.0\" class=\"e b3\"/><rect x=\"20\" y=\"92\" width=\"200\" height=\"150\" rx=\"2\" class=\"box2 b2\"/><text x=\"120.0\" y=\"144.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">침엽수 (소프트우드)<\/text><text x=\"120.0\" y=\"163.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">겉씨식물, 상록수<\/text><text x=\"120.0\" y=\"182.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">비중이 비교적 낮음<\/text><text x=\"120.0\" y=\"202.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">건축재 선호<\/text><rect x=\"260\" y=\"92\" width=\"200\" height=\"150\" rx=\"2\" class=\"box b3\"/><text x=\"360.0\" y=\"144.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b3\">활엽수 (하드우드)<\/text><text x=\"360.0\" y=\"163.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">속씨식물, 낙엽수<\/text><text x=\"360.0\" y=\"182.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">밀도, 강도가 높음<\/text><text x=\"360.0\" y=\"202.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">가구 선호<\/text><\/svg>","caption":"침엽수는 겉씨식물, 활엽수는 속씨식물이에요. 은행나무는 구과목이 아닌 유일한 겉씨식물이에요.","builds":3},{"kind":"points","head":"대표 수종","items":["**침엽수재(Softwood)** : 삼나무, 소나무, 전나무, 잣나무, 낙엽송","**활엽수재(Hardwood)** : 자작나무, 물푸레나무, 벚나무, 흑단, 너도밤나무, 마호가니, 단풍나무"]},{"kind":"compare","head":"북미 소프트우드","cols":["수종","한 가지 특징"],"rows":[["스프루스(가문비나무)","무게에 비해 강도가 좋아 목조 건물 골격"],["레드파인(미국 적송)","건축용으로 널리 사용"],["홍송(더글라스퍼)","오레곤 파인이라고도 함, 건축 구조재, 합판, 가구"],["미송(햄록)","접착, 도장성 양호하나 수분에 약함"],["적삼목(시더)","가볍고 무르지만 향이 좋고 수분에 강함"]]},{"kind":"compare","head":"북미 하드우드","cols":["수종","한 가지 특징"],"rows":[["화이트 오크","나무껍질이 밝은 회색, 고급 원목 제품에 가장 널리"],["레드오크","낙엽색이 붉어서 레드, 목재 색은 붉지 않음"],["월넛","어두운 초콜렛 갈색의 **심재(Heartwood)**, 뒤틀림, 갈라짐에 강함"],["메이플","흰색 계통 **변재(Sapwood)** 를 많이 씀, 마감 후 황변이 심한 편"],["체리","다소 붉은 빛, 결이 아름답고 조밀함"]]},{"kind":"compare","head":"그 밖의 하드우드","cols":["수종","한 가지 특징"],"rows":[["자작나무","원목은 수축, 변형이 심해 주로 합판으로 써요"],["마호가니","가구용 최고 목재, 악기 제작에도 써요"],["에보니(흑단)","검은 심재를 쓰고 물에 가라앉기도 해요"],["티크","오일이 많아 물과 습기에 강해 야외용 가구"],["퍼플하트","노출되면 보라색으로 변해요"]]},{"kind":"compare","head":"한국 목재","cols":["수종","한 가지 특징"],"rows":[["오동나무","가볍고 잘 틀어지지 않음, 심은 지 10년이면 사용"],["참죽나무","단단하고 휘거나 뒤틀리지 않음"],["느티나무","무늬가 좋아 으뜸으로 쳤고 오래될수록 좋음"],["(먹)감나무","검은 무늬가 번진 나무를 귀하게 여김"]]},{"kind":"check","q":"벌목 후 건조가 빠르고 곧게 자라 크고 긴 재료를 얻을 수 있는 목재는?","choices":["침엽수재","활엽수재"],"a":0,"why":"침엽수재는 바늘잎, 연목이고 건축재로 선호돼요."},{"kind":"check","q":"레드오크의 레드는 무엇의 색인가요?","choices":["목재 색","낙엽 색","껍질 색"],"a":1,"why":"낙엽색이 붉어서 레드 오크예요. 목재 색은 붉지 않아요."},{"kind":"warn","head":"헷갈리는 점","items":["침엽수 비중은 본문 0.3~0.5, 분류표 그림은 0.30~0.55 로 서로 달라요","슬라이드 표기가 스프루스와 스프러스로 섞여 있어요","레드오크 이름은 목재 색이 아니라 낙엽색에서 왔어요"]},{"kind":"english","head":"답안에 쓸 문장","en":"침엽수재는 연목으로 건조가 빠르고 크고 긴 재료를 얻어 건축재로, 활엽수재는 경목으로 가구재로 선호된다.","ko":"잎 모양, 단단함, 건조, 쓰임 네 칸을 짝으로 써요"},{"kind":"recap","items":["**침엽수재(Softwood)** 는 바늘잎, 연목, 빠른 건조, 건축재예요","**활엽수재(Hardwood)** 는 넓은잎, 경목, 느린 건조, 가구재예요","**비중** 은 활엽수 쪽이 높아요","월넛은 **심재(Heartwood)**, 메이플은 **변재(Sapwood)** 를 많이 써요","티크는 야외용, 오동나무는 가볍고, 에보니는 물에 가라앉기도 해요","오늘의 용어: 침엽수재(Softwood), 활엽수재(Hardwood), 비중, 심재(Heartwood), 변재(Sapwood)"]}]},{"id":"w4-4","title":"용도, 건조, 취재 방법, 취급 단위","goal":"구조용재와 치장용재, 자연건조와 인공 건조, 정목과 판목, 나뭇결 네 가지, 재래 단위를 말할 수 있어요","terms":[{"ko":"구조용재","en":"","say":"실내 건축에서 뼈대 역할을 하는 목재","more":"강도와 내구성 필요, 수축팽창이 작고 내부식성이 큰 것."},{"ko":"치장용재","en":"","say":"마무리 공사에 쓰여 그대로 마감이 되는 목재, 수장용재라고도 함","more":"색상과 무늬결이 아름답고 쉽게 마모되지 않는 것."},{"ko":"자연건조","en":"","say":"대기의 온도, 습도, 바람으로 자연 그대로 말리는 방법","more":"간단하고 시설비 적음, 인공 건조의 선행 과정. 6개월~3~5년, 함수율 25~30% 내외."},{"ko":"인공 건조","en":"","say":"건조실의 온도, 습도, 풍속을 조절해 말리는 방법","more":"낮은 함수율까지 가능, 자연 조건 영향 없음, 설치비와 유지비 높음, 체적 감소와 균열."},{"ko":"정목","en":"quarter sawn","say":"나이테와 직각으로 중심을 향해 켠 판재, 곧은 결재","more":"변형, 마모 적어 이상적. 넓은 판이 적게 나와 비쌈."},{"ko":"판목","en":"flat sawn","say":"나이테 방향을 무시하고 켠 판재, 널 결재","more":"결이 물결 모양 곡선. 곧은 결재보다 갈라짐, 틀어짐이 많음."},{"ko":"곧은결","en":"","say":"나이테에 직각방향으로 켠 면에 나타나는 평행선 나뭇결","more":"수축, 변형, 마모 적음. 창호재, 장식재, 가구재."},{"ko":"널결","en":"","say":"나이테에 평행방향으로 켠 면에 나타나는 물결 모양 나뭇결","more":"결이 거칠고 불규칙, 변형과 마모 큼. 주로 장식재."},{"ko":"재래 단위","en":"","say":"푼, 치, 자로 재는 옛 목재 치수 단위","more":"푼 3mm, 치 30mm, 자 300mm. 2001년부터 사용 금지, 치수는 주로 300mm 단위."}],"slides":[{"kind":"title","big":"쓰임, 말리기, 켜기","sub":"목재를 나누는 네 가지 잣대"},{"kind":"goal","items":["구조용재와 치장용재를 구별해요","자연건조와 인공 건조를 비교해요","정목과 판목, 나뭇결 네 가지를 구별해요","푼, 치, 자를 mm 로 바꿔요"]},{"kind":"analogy","head":"통나무 케이크 자르기","scene":"가운데를 향해 부채꼴로 자르면 줄무늬가 곧고, 가로로 나란히 썰면 물결무늬가 돼요.","map":[["가운데를 향해 자른 조각","**정목(quarter sawn)**"],["나란히 썬 조각","**판목(flat sawn)**"],["곧은 줄무늬와 물결무늬","**곧은결** 과 **널결**"]]},{"kind":"compare","head":"용도에 따른 분류","cols":["분류","필요한 성질"],"rows":[["**구조용재**","뼈대 역할, 강도와 내구성, 수축팽창이 작고 내부식성이 큼"],["**치장용재**","마무리 공사용, 수장용재라고도 함, 색과 무늬결이 아름답고 마모 적음"]]},{"kind":"points","head":"4-1 과 이어 보기","items":["**구조용재** 는 **구조적 측면** 의 쓰임에 맞춰 골라요","**치장용재** 는 재료 자체가 마감이 되므로 겉모습이 중요해요","구조목으로 레드 파인, 노르딕 스프러스, 더글라스 퍼, 헴록 등을 써요"]},{"kind":"points","head":"건조의 기본","items":["사용할 용도의 **함수율** 까지 건조해서 써야 해요","일반적으로 활엽수는 침엽수보다 건조가 어려워요","수종에 따라 건조 특성이 달라 알맞은 건조 방법을 적용해요","건조목재는 원목보다 접착성과 도장성이 좋아져요"]},{"kind":"compare","head":"두 가지 건조","cols":["구분","자연건조","인공 건조"],"rows":[["방법","대기의 온도, 습도, 바람","건조실의 온도, 습도, 풍속 조절"],["좋은 점","간단, 시설비 적음, 특수 기술 불필요","낮은 함수율까지, 자연 조건 영향 없음"],["약점","기간이 길고 자연 조건에 따라 달라짐","설치비와 유지비 높음, 균열 발생"]]},{"kind":"points","head":"**자연건조** 와 **인공 건조** 의 숫자","items":["**자연건조** 는 짧게는 6개월, 길게는 3~5년 해요","이때 수분 함량은 25~30% 내외예요","**자연건조** 는 **인공 건조** 의 선행 과정이기도 해요","**인공 건조** 로 세포벽 속 물이 빠지면 단단해지지만 체적이 줄고 균열이 생겨요"]},{"kind":"figure","head":"통나무를 켜는 두 방법","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"30.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b1\">같은 통나무, 다른 톱질<\/text><circle cx=\"120.0\" cy=\"140.0\" r=\"90\" class=\"n b1\"/><line x1=\"120.0\" y1=\"140.0\" x2=\"210.0\" y2=\"140.0\" class=\"e2 b1\"/><line x1=\"120.0\" y1=\"140.0\" x2=\"30.0\" y2=\"140.0\" class=\"e2 b1\"/><line x1=\"120.0\" y1=\"140.0\" x2=\"120.0\" y2=\"50.0\" class=\"e2 b1\"/><line x1=\"120.0\" y1=\"140.0\" x2=\"120.0\" y2=\"230.0\" class=\"e2 b1\"/><line x1=\"120.0\" y1=\"140.0\" x2=\"183.6\" y2=\"76.4\" class=\"e2 b1\"/><line x1=\"120.0\" y1=\"140.0\" x2=\"56.4\" y2=\"76.4\" class=\"e2 b1\"/><line x1=\"120.0\" y1=\"140.0\" x2=\"183.6\" y2=\"203.6\" class=\"e2 b1\"/><line x1=\"120.0\" y1=\"140.0\" x2=\"56.4\" y2=\"203.6\" class=\"e2 b1\"/><text x=\"120.0\" y=\"258.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">정목 : 중심을 향해 켜요<\/text><circle cx=\"360.0\" cy=\"140.0\" r=\"90\" class=\"n b2\"/><line x1=\"293.0\" y1=\"80.0\" x2=\"427.0\" y2=\"80.0\" class=\"e2 b2\"/><line x1=\"275.0\" y1=\"110.0\" x2=\"445.0\" y2=\"110.0\" class=\"e2 b2\"/><line x1=\"270.0\" y1=\"140.0\" x2=\"450.0\" y2=\"140.0\" class=\"e2 b2\"/><line x1=\"275.0\" y1=\"170.0\" x2=\"445.0\" y2=\"170.0\" class=\"e2 b2\"/><line x1=\"293.0\" y1=\"200.0\" x2=\"427.0\" y2=\"200.0\" class=\"e2 b2\"/><text x=\"360.0\" y=\"258.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">판목 : 나란히 켜요<\/text><\/svg>","caption":"왼쪽은 나이테와 직각으로 중심을 향해 켠 정목, 오른쪽은 나이테 방향을 무시하고 켠 판목이에요.","builds":2},{"kind":"compare","head":"켜는 방법 두 가지","cols":["구분","정목","판목"],"rows":[["다른 이름","곧은 결재","널 결재"],["켜는 법","톱과 나이테가 직각, 중심을 향해","나이테의 방향을 무시하고 자른 것"],["결 모양","세로로 평행","물결모양 곡선"],["변형과 값","변형, 마모 적음, 가격이 다소 높음","갈라짐, 틀어짐이 더 생김"]]},{"kind":"compare","head":"나뭇결 네 가지","cols":["결","모양과 쓰임"],"rows":[["**곧은결**","나이테에 직각으로 켠 면의 평행선, 창호재, 장식재, 가구재"],["**널결**","나이테에 평행으로 켠 면의 물결, 결이 거칠고 주로 장식재"],["**엇결**","나무 섬유가 꼬여 나뭇결이 어긋난 상태"],["**무늬결**","소용돌이처럼 복잡하고 아름다운 무늬, 주로 장식재"]]},{"kind":"compare","head":"**재래 단위**","cols":["단위","mm"],"rows":[["푼","3mm"],["치","30mm"],["자","300mm"]]},{"kind":"points","head":"**재래 단위** 이야기","items":["2001년부터 사용이 금지돼 mm 단위를 쓰는 추세예요","그래도 현장에서는 종종 아직 써요","치수는 주로 300mm 단위로 커지거나 작아져요, 4-5 의 합판 4x8자에서 다시 나와요"]},{"kind":"check","q":"톱과 나이테가 직각이 된 상태에서 중심을 향해 켠, 곧은 결재라고도 하는 것은?","choices":["정목","판목","엇결재"],"a":0,"why":"정목은 변형과 마모가 적어 이상적이지만 넓은 판이 적게 나와 비싸요."},{"kind":"check","q":"낮은 함수율까지 건조할 수 있지만 설치비와 유지비가 높은 건조는?","choices":["자연건조","인공 건조"],"a":1,"why":"인공 건조는 자연 조건의 영향을 받지 않지만 시설비가 들어요."},{"kind":"warn","head":"판목 정의를 읽을 때","items":["판목 정의 첫 구절 '중심을 향하여 직각으로 켠 것' 은 정목 정의와 거의 같아 헷갈려요","구별은 '나이테의 방향을 무시하고 자른 것' 과 물결모양 결로 해요","나이테에 평행으로 켠 면이 **널결**, 직각으로 켠 면이 **곧은결** 이에요"]},{"kind":"recap","items":["**구조용재** 는 강도, **치장용재** 는 색과 무늬결이에요","**자연건조** 는 싸고 오래, **인공 건조** 는 낮은 함수율까지 비싸게예요","**정목(quarter sawn)** 은 곧은 결재, **판목(flat sawn)** 은 널 결재예요","**곧은결** 은 직각, **널결** 은 평행으로 켠 면이에요","**재래 단위** 는 푼 3, 치 30, 자 300mm 예요","오늘의 용어: 구조용재, 치장용재, 자연건조, 인공 건조, 정목(quarter sawn), 판목(flat sawn), 곧은결, 널결, 재래 단위"]}]},{"id":"w4-5","title":"각재와 합판","goal":"각재의 정의와 현장 이름, 길이 구분, 합판의 제조와 특성, 크기를 말할 수 있어요","terms":[{"ko":"각재","en":"","say":"막대기 모양으로 각지게 켠 목재","more":"두께 75mm 미만, 폭이 두께의 4배 미만 또는 두께와 폭 모두 75mm 이상. 30, 45, 60, 75, 90각. 대부분 3,600mm."},{"ko":"평각재","en":"","say":"단면이 직사각형인 각재","more":"짝은 정각재(정사각형). 현장 통칭 중각재, 투바이. 30×69 / 38×64 등."},{"ko":"소각재","en":"","say":"현장 용어 다루끼, 가장 가는 각재","more":"28×28 또는 30×30. 가구 프레임, 벽체 틀. 대각재(오비끼)는 81×81 / 89×89, 문틀."},{"ko":"정척물","en":"","say":"1.8m, 2.7m, 3.6m 길이의 각재","more":"3.6m가 가장 많이 씀. 장척물 4.5, 5.4, 6.3m / 단척물 1.8m 이하 / 난척물 2.1, 2.4, 3.0m."},{"ko":"나왕","en":"lauan","say":"색이 아름답고 가공이 쉬운 각재 수종, 라왕이라고도 함","more":"적나왕과 백나왕. 문틀, 문짝, 가구, 바닥재. 미송은 나왕보다 저가."},{"ko":"합판","en":"Plywood","say":"얇은 단판을 섬유방향이 직교하게 홀수 겹 붙인 판재","more":"단판 0.5~1.5mm, 3, 5, 7겹. 두께 3~24mm, 3x6자 910x1,820, 4x8자 1,220x2,440(주로)."},{"ko":"단판","en":"","say":"원목을 얇게 깎은 한 장의 박판, 베니어","more":"단판 여러 겹인 합판을 베니어판이라 부르는 것은 잘못."},{"ko":"특수합판","en":"","say":"표면에 오버레이, 프린트, 도장 등을 가공한 합판","more":"짝은 보통합판(표면가공 없음). 용도별 : 내수, 방충, 방화, 방부합판."}],"slides":[{"kind":"title","big":"막대와 판","sub":"뼈대는 각재, 덮개는 합판"},{"kind":"goal","items":["각재의 정의 문장과 현장 이름을 외워요","정척물, 장척물, 단척물, 난척물을 구별해요","합판의 제조와 특성, 크기를 말해요"]},{"kind":"analogy","head":"뼈와 피부","scene":"각재는 몸의 뼈, 합판은 뼈를 덮는 피부예요. 3강의 스터드와 석고보드 관계와 같아요.","map":[["뼈","**각재**"],["피부","**합판(Plywood)**"],["피부 한 겹 한 겹","**단판**"]]},{"kind":"points","head":"**각재** 의 정의","items":["**각재** 는 두께 75mm 미만이고 폭이 두께의 4배 미만인 막대기 모양 목재예요","두께와 폭이 모두 75mm 이상인 것도 **각재** 예요","횡단면이 정사각형이면 정각재, 직사각형이면 **평각재** 예요"]},{"kind":"points","head":"쓰임과 치수","items":["목조 벽틀, 칸막이 같은 구조틀, 창호 틀, 가구 뼈대에 써요","**구조용재** 처럼 하중에 견디는 내구성 수종을 써요","30각, 45각, 60각, 75각, 90각이 많이 쓰여요","대부분 3,600mm 길이로 통용돼요","가구 프레임과 벽체 틀에는 가장 가는 **소각재** 를 써요"]},{"kind":"compare","head":"현장 이름과 규격","cols":["통칭","규격(mm)","용도"],"rows":[["**소각재** (다루끼)","28×28, 30×30","가구 프레임, 벽체 틀"],["중각재, **평각재** (투바이)","30×69, 38×64","파티션 프레임, 몰딩 하부재"],["대각재 (오비끼)","81×81, 89×89","문틀, 큰 틀 구조"]]},{"kind":"compare","head":"길이로 나누기","cols":["구분","길이"],"rows":[["**정척물**","1.8m, 2.7m, 3.6m (3.6m 가장 많이 사용)"],["장척물","4.5m, 5.4m, 6.3m (정척물보다 긴 것)"],["단척물","1.8m 이하"],["난척물","2.1m, 2.4m, 3.0m (정척물이 아닌 것)"]]},{"kind":"compare","head":"각재 수종","cols":["수종","특징"],"rows":[["**나왕(lauan)**","빛깔이 아름답고 가공 쉬움, 문틀, 문짝, 가구"],["미송","**나왕(lauan)** 에 비해 저가, 부드럽고 향기가 좋음"],["소송","러시아산, 옹이 적고 밝음, 미송보다 비쌈"],["뉴송","뉴질랜드산, 저렴하지만 옹이 주변 못에 갈라짐"]]},{"kind":"figure","head":"합판은 결을 엇갈려 쌓아요","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"40.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b1\">단판 한 장 = 0.5~1.5mm<\/text><rect x=\"100\" y=\"60\" width=\"280\" height=\"40\" rx=\"2\" class=\"n b1\"/><line x1=\"110.0\" y1=\"72.0\" x2=\"370.0\" y2=\"72.0\" class=\"e b1\"/><line x1=\"110.0\" y1=\"88.0\" x2=\"370.0\" y2=\"88.0\" class=\"e b1\"/><text x=\"390.0\" y=\"85.0\" font-size=\"14\" text-anchor=\"start\" class=\"tm b1\">결 가로<\/text><rect x=\"100\" y=\"105\" width=\"280\" height=\"40\" rx=\"2\" class=\"n3 b2\"/><line x1=\"130.0\" y1=\"108.0\" x2=\"130.0\" y2=\"142.0\" class=\"e b2\"/><line x1=\"170.0\" y1=\"108.0\" x2=\"170.0\" y2=\"142.0\" class=\"e b2\"/><line x1=\"210.0\" y1=\"108.0\" x2=\"210.0\" y2=\"142.0\" class=\"e b2\"/><line x1=\"250.0\" y1=\"108.0\" x2=\"250.0\" y2=\"142.0\" class=\"e b2\"/><line x1=\"290.0\" y1=\"108.0\" x2=\"290.0\" y2=\"142.0\" class=\"e b2\"/><line x1=\"330.0\" y1=\"108.0\" x2=\"330.0\" y2=\"142.0\" class=\"e b2\"/><text x=\"390.0\" y=\"130.0\" font-size=\"14\" text-anchor=\"start\" class=\"tm b2\">결 세로<\/text><rect x=\"100\" y=\"150\" width=\"280\" height=\"40\" rx=\"2\" class=\"n b3\"/><line x1=\"110.0\" y1=\"162.0\" x2=\"370.0\" y2=\"162.0\" class=\"e b3\"/><line x1=\"110.0\" y1=\"178.0\" x2=\"370.0\" y2=\"178.0\" class=\"e b3\"/><text x=\"390.0\" y=\"175.0\" font-size=\"14\" text-anchor=\"start\" class=\"tm b3\">결 가로<\/text><text x=\"240.0\" y=\"230.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">결을 직교, 3겹, 5겹, 7겹 홀수로 쌓아요<\/text><\/svg>","caption":"섬유방향이 서로 직교되게 홀수 겹으로 붙여요. 슬라이드 표시는 방향성 보완 방법 = 직교예요.","builds":3},{"kind":"points","head":"**합판(Plywood)** 만들기","items":["원목을 0.5~1.5mm 로 깎은 **단판** 을 건조, 가공해요","섬유방향이 서로 직교되게 3겹, 5겹, 7겹 등 홀수로 쌓아요","층마다 접착제를 바르고 압력을 가해 표면을 평활하게 해요"]},{"kind":"points","head":"**합판(Plywood)** 의 특성","items":["원목보다 강도가 크고 넓은 판을 대량으로 만들어요","흠, 갈라짐, 옹이 같은 결점이 제거돼요","방향성 보완 방법은 직교, 방향에 따른 강도 차이가 거의 없어요","팽창, 수축을 방지할 수 있어요"]},{"kind":"compare","head":"**합판(Plywood)** 의 숫자","cols":["항목","값"],"rows":[["두께","3, 6, 9, 12, 15, 18, 21, 24mm"],["**재래 단위** 3x6자","910 x 1,820mm"],["4x8자 (주로 사용)","1,220 x 2,440mm"]]},{"kind":"compare","head":"**합판(Plywood)** 의 분류","cols":["기준","종류"],"rows":[["표면 가공","보통합판, **특수합판** (오버레이, 프린트, 도장)"],["용도","내수, 방충, 방화, 방부합판"],["수종","나왕, 미송, 낙엽송, 자작나무 합판"]]},{"kind":"check","q":"단판 한 장을 뜻하는 말이라서, 합판을 이렇게 부르면 잘못인 이름은?","choices":["베니어판","특수합판","평각재"],"a":0,"why":"베니어판은 한 장의 박판(단판)이에요. 여러 겹 붙인 합판과 달라요."},{"kind":"check","q":"각재 정척물 중 가장 많이 사용하는 길이는?","choices":["1.8m","3.6m","6.3m"],"a":1,"why":"정척물은 1.8, 2.7, 3.6m 이고 3.6m 를 가장 많이 써요. 6.3m 는 장척물이에요."},{"kind":"warn","head":"헷갈리는 점","items":["**합판(Plywood)** 은 결을 직교, 홀수 겹이에요, 짝수나 평행이 아니에요","흔히 부르는 베니어판은 **단판** 한 장이라 **합판(Plywood)** 과 달라요","중각재는 현장에서 투바이라 부르지만 원뜻 2×4인치 규격(약 38×89mm)과는 치수가 달라요"]},{"kind":"english","head":"답안에 쓸 문장","en":"합판은 0.5~1.5mm 단판을 섬유방향이 직교되게 홀수로 적층해 방향에 따른 강도 차이를 줄인 판재이다.","ko":"직교, 홀수, 강도 차이 세 낱말을 꼭 넣어요"},{"kind":"recap","items":["**각재** 는 두께 75mm 미만, 폭이 두께의 4배 미만인 막대예요","**소각재** 는 다루끼, **평각재** 는 투바이, 대각재는 오비끼예요","**정척물** 은 1.8, 2.7, 3.6m 이고 3.6m 가 가장 많아요","**합판(Plywood)** 은 **단판** 을 직교, 홀수 겹, 4x8자 1,220 x 2,440mm 예요","**나왕(lauan)** 은 문틀과 가구, **특수합판** 은 표면 가공 합판이에요","오늘의 용어: 각재, 평각재, 소각재, 정척물, 나왕(lauan), 합판(Plywood), 단판, 특수합판"]}]},{"id":"w4-6","title":"MDF, 파티클 보드와 여러 가공 판재","goal":"MDF, 파티클 보드, 코아 합판, OSB, 집성목을 재료 모양으로 구별하고 무늬목과 장식 판재를 말할 수 있어요","terms":[{"ko":"MDF","en":"Medium Density Fiber Board","say":"나무를 톱밥처럼 부숴 합성수지로 굳힌 중밀도 섬유판","more":"방향성 없음, 가공성 좋음. 수축되기 쉽고 습기에 약하며 합판보다 약함. 1,220×2,440, 3~30mm, 18T 주로 사용. 도장은 프라이머 필수."},{"ko":"파티클 보드","en":"Particle Board","say":"목재 조각을 잘게 부순 칩을 붙인 자원 절약형 판, PB, 칩 보드","more":"흡음성, 단열성 좋음, 단면이 거칠어 측면 가공 필요. 두께 9~35mm. 씽크대, 가구."},{"ko":"코아 합판","en":"Core Plywood","say":"띠 모양 각목 심 위아래에 단판을 붙인 판재","more":"정확한 명칭 Batten Board. 두께 18~25mm. 띠로 잘라 각재 대신 틀로 쓰기도 함."},{"ko":"OSB","en":"Oriented Strand Board","say":"얇은 직사각형 나무 조각을 직각으로 겹쳐 내수수지로 누른 판","more":"포장 합판. 조각은 부산물이 아니라 특별히 제조. 파티클 보드보다 강함. 파티션, 가구, 최종 마감."},{"ko":"집성목","en":"Glue-Laminated Timber","say":"각재를 섬유방향 평행하게 접착해 모은 목재","more":"변형 적고 긴 장척재. 구조용 집성목, 수장용 집성목. 합판은 직교, 집성목은 평행."},{"ko":"핑거 조인트","en":"Finger-Joint","say":"손가락 깍지처럼 끝을 맞물려 길이 방향으로 잇는 접합","more":"짝은 스카프 조인트(Scarf-Joint, 비스듬히 깎아 잇기). 구조용 집성목에 포함."},{"ko":"흡음패널","en":"Acoustic panel","say":"강당, 연주 공간에 쓰는 흡음용 목재 마감 판재","more":"코펜하겐 리브를 대신하는 저렴한 재료. 흡음재료는 다공성."},{"ko":"무늬목","en":"Wood Veneer","say":"원목을 0.2mm로 종이처럼 얇게 뜬 장식재","more":"석고보드, 합판에 가열, 가압으로 부착. 들뜸, 터짐 하자. 1mm 이상 후판은 배접 생산."},{"ko":"로터리 컷","en":"","say":"원목을 돌리며 두루마리 풀듯 단판을 깎는 방법","more":"나이테를 따라 깎여 폭이 넓고 판목상 무늬. 짝은 슬라이스 컷(고정하고 칼로 저밈)."},{"ko":"템바보드","en":"Tambour Board","say":"막대를 반복 배열해 세로나 가로 요철을 만든 장식 마감재","more":"벽체, 가구 전면, 카운터, 기둥. 홈에 먼지, 돌출부 손상 주의."}],"slides":[{"kind":"title","big":"부숴서 다시 붙인 판","sub":"부순 모양으로 판 이름이 갈려요"},{"kind":"goal","items":["MDF, 파티클 보드, 코아 합판, OSB, 집성목을 구별해요","무늬목의 두께와 뜨는 방법을 말해요","흡음패널과 템바보드의 쓰임을 말해요"]},{"kind":"analogy","head":"부순 과자 다시 굳히기","scene":"과자를 가루로 빻아 굳히면 매끈한 판, 조각째 굳히면 울퉁불퉁한 판이 돼요.","map":[["가루로 굳힌 판","**MDF(Medium Density Fiber Board)**"],["조각째 굳힌 판","**파티클 보드(Particle Board)**"],["막대를 나란히 붙인 판","**집성목(Glue-Laminated Timber)**"]]},{"kind":"points","head":"**MDF(Medium Density Fiber Board)** 란","items":["목재를 파쇄한 톱밥에 합성수지 접착제를 분무하고 열과 압력으로 붙여요","섬유분배가 균일해 면이 평활하고 방향성이 없어요","건조 공정 없이 바로 쓰고, 도장, 필름, 무늬목을 바로 붙여요","도장할 때는 프라이머가 필수예요, 안 하면 페인트가 흡수돼요"]},{"kind":"compare","head":"MDF 의 숫자와 약점","cols":["항목","내용"],"rows":[["판재 크기","1,220mm × 2,440mm"],["두께","3T 에서 30T, 18T 를 주로 사용"],["약점","시공 후 수축, 습기에 약함, **합판(Plywood)** 보다 강도 낮음"],["쓰임","프레임, 몰딩, 가구 구조틀, 선반, 서랍 측면"]]},{"kind":"points","head":"**파티클 보드(Particle Board)**","items":["남은 나무 조각을 부순 칩으로 만든 자원 절약형이에요, 칩 보드라고도 해요","결 방향 강도 차이가 없고 흡음성, 단열성이 좋아요","단면이 거칠어 측면 가공이 필요하고 두께는 9~35mm 예요","씽크대와 가구에 많이 쓰고 바탕, 홑겹 붙임, 양겹 붙임이 있어요"]},{"kind":"figure","head":"판재 다섯 가지","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"10\" y=\"40\" width=\"146\" height=\"90\" rx=\"2\" class=\"box2 b1\"/><text x=\"83.0\" y=\"72.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">MDF<\/text><text x=\"83.0\" y=\"92.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">톱밥(섬유)<\/text><text x=\"83.0\" y=\"110.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">방향성 없음<\/text><rect x=\"167\" y=\"40\" width=\"146\" height=\"90\" rx=\"2\" class=\"box b1\"/><text x=\"240.0\" y=\"72.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">파티클 보드<\/text><text x=\"240.0\" y=\"91.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">부순 칩<\/text><text x=\"240.0\" y=\"110.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">흡음, 단열<\/text><rect x=\"324\" y=\"40\" width=\"146\" height=\"90\" rx=\"2\" class=\"box b1\"/><text x=\"397.0\" y=\"72.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">코아 합판<\/text><text x=\"397.0\" y=\"91.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">띠 모양 각목 심<\/text><text x=\"397.0\" y=\"110.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">18~25mm<\/text><rect x=\"88\" y=\"145\" width=\"146\" height=\"90\" rx=\"2\" class=\"box b2\"/><text x=\"161.0\" y=\"178.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b2\">OSB<\/text><text x=\"161.0\" y=\"196.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">조각을 직각으로<\/text><text x=\"161.0\" y=\"216.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">포장 합판<\/text><rect x=\"245\" y=\"145\" width=\"146\" height=\"90\" rx=\"2\" class=\"box2 b2\"/><text x=\"318.0\" y=\"177.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">집성목<\/text><text x=\"318.0\" y=\"196.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">각재를 평행으로<\/text><text x=\"318.0\" y=\"215.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">긴 장척재<\/text><text x=\"240.0\" y=\"262.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b2\">부순 모양이 판의 이름을 정해요<\/text><\/svg>","caption":"톱밥이면 MDF, 칩이면 파티클 보드, 띠 각목이면 코아 합판, 직각 조각이면 OSB, 평행 각재면 집성목이에요.","builds":2},{"kind":"points","head":"**코아 합판(Core Plywood)**","items":["띠 모양 각목 심 위아래에 **단판** 을 붙인 판이에요","정확한 명칭은 Batten Board 예요, Batten 은 작은 각목이에요","두께는 18~25mm 를 주로 쓰고 띠로 잘라 각재 대신 틀을 짜기도 해요"]},{"kind":"points","head":"**OSB(Oriented Strand Board)** 와 **집성목(Glue-Laminated Timber)**","items":["**OSB(Oriented Strand Board)** 는 특별히 만든 얇은 조각을 직각으로 겹쳐 내수수지로 압착해요","포장 합판이라고도 하고 **파티클 보드(Particle Board)** 보다 강도가 높아요","**집성목(Glue-Laminated Timber)** 은 각재를 섬유방향 평행으로 접착해 긴 장척재를 얻어요","길이 이음은 스카프 조인트와 **핑거 조인트(Finger-Joint)** 예요"]},{"kind":"compare","head":"직교와 평행","cols":["판","결 방향"],"rows":[["**합판(Plywood)**","단판을 직교, 홀수 겹"],["**집성목(Glue-Laminated Timber)**","각재를 평행으로 접착, 길이는 **핑거 조인트(Finger-Joint)** 등으로 이음"],["**OSB(Oriented Strand Board)**","조각을 직각으로 겹쳐 배열"]]},{"kind":"points","head":"**흡음패널(Acoustic panel)** 과 **템바보드(Tambour Board)**","items":["**흡음패널(Acoustic panel)** 은 코펜하겐 리브를 대신하는 저렴한 흡음 판재예요","강당, 연주 공간에 쓰고 흡음재료는 표면이 거친 다공성이에요","**템바보드(Tambour Board)** 는 막대를 반복 배열해 세로나 가로 요철을 만든 장식재예요","홈에 먼지가 쌓이고 돌출부가 충격에 손상될 수 있어요"]},{"kind":"points","head":"**무늬목(Wood Veneer)**","items":["**무늬목(Wood Veneer)** 은 원목을 0.2mm 로 종이처럼 얇게 가공한 장식재예요","석고보드나 **합판(Plywood)** 에 접착제를 바르고 가열, 가압으로 붙여요","들뜸과 터짐 하자가 생길 수 있어요, 1mm 이상 후판은 배접해 생산해요","외장재로는 거의 쓰지 않아요"]},{"kind":"compare","head":"단판을 뜨는 두 방법","cols":["방법","어떻게"],"rows":[["**로터리 컷**","원목을 회전시켜 두루마리 풀듯 깎아요, 폭이 매우 넓어요"],["슬라이스 컷","원목을 고정하고 칼이 움직여 한 장씩 떠내요"]]},{"kind":"steps","head":"**무늬목(Wood Veneer)** 제작 과정","steps":["원목을 구입해요","제재 및 절삭으로 면을 다듬어요","삶아 연하게 하고 표면을 청소해요","**로터리 컷** 이나 슬라이스 컷으로 생산해요","재단하고 진공건조기로 건조해요","남은 목재는 판재로 만들어 팔아요"],"answer":"구입, 제재, 다듬기, 생산, 재단, 건조, 남은 목재 활용 순서예요"},{"kind":"check","q":"목재 톱밥에 합성수지 접착제를 넣어 열압한 중밀도 섬유판은?","choices":["MDF","OSB","코아 합판"],"a":0,"why":"OSB 는 직각으로 겹친 조각, 코아 합판은 띠 모양 각목 심이에요."},{"kind":"check","q":"각재를 섬유방향 평행으로 접착해 길이가 긴 장척재를 얻는 것은?","choices":["합판","집성목","파티클 보드"],"a":1,"why":"합판은 직교, 집성목은 평행이에요."},{"kind":"warn","head":"슬라이드끼리 다른 곳","items":["**로터리 컷** 은 p53 에서 판목상의 무늬가 나타난다고 적혀 있어요","그런데 p56 본문은 정목은 로터리 컷, 판목은 슬라이스 컷이라고 적어요","MDF 두께는 3mm 배수라 적혀 있지만 4.5T, 20T, 22T, 25T 도 함께 있어요"]},{"kind":"recap","items":["**MDF(Medium Density Fiber Board)** 는 톱밥, 18T, 습기에 약하고 프라이머 필수예요","**파티클 보드(Particle Board)** 는 칩, **코아 합판(Core Plywood)** 은 Batten Board 18~25mm 예요","**OSB(Oriented Strand Board)** 는 포장 합판, **집성목(Glue-Laminated Timber)** 은 평행, **핑거 조인트(Finger-Joint)** 이음","**무늬목(Wood Veneer)** 은 0.2mm, **로터리 컷** 은 돌려 깎기예요","**흡음패널(Acoustic panel)** 은 강당, **템바보드(Tambour Board)** 는 반복 요철 장식이에요","오늘의 용어: MDF(Medium Density Fiber Board), 파티클 보드(Particle Board), 코아 합판(Core Plywood), OSB(Oriented Strand Board), 집성목(Glue-Laminated Timber), 핑거 조인트(Finger-Joint), 흡음패널(Acoustic panel), 무늬목(Wood Veneer), 로터리 컷, 템바보드(Tambour Board)"]}]},{"id":"w4-7","title":"마루판재와 몰딩재","goal":"마루 네 가지를 가격 순서로 말하고, 강화마루와 강마루를 바탕재와 시공법으로 구별할 수 있어요","terms":[{"ko":"원목마루","en":"","say":"통원목이나 두꺼운 원목 단판을 쓴 가장 비싼 마루","more":"샌딩 후 재도장 가능, 정전기 없음. 습기와 온도 변화에 약함. 합판 위 무늬목 2mm 이상."},{"ko":"합판마루","en":"","say":"합판 위에 천연 무늬목을 붙인 마루, 온돌마루","more":"치수 안정성 높고 바닥난방에 적합, 긁힘에 약함. 무늬목 2mm 이하. 중/고가."},{"ko":"강화마루","en":"","say":"HDF 위에 무늬층을 얹어 접착제 없이 클릭으로 끼우는 마루","more":"현가식, 비접착식, 저가. 시공, 철거 쉬움, 보행 소음, 습기 주의. 걸레받이와 사이 실리콘 금지."},{"ko":"강마루","en":"","say":"합판 위에 인쇄 무늬층을 얹어 바닥에 본드로 붙이는 마루","more":"접착식, 중가. 들뜸, 울림 적고 열전달 유리. 철거와 부분 교체 어려움. 아파트에 많이 씀."},{"ko":"HDF","en":"","say":"목질섬유를 고밀도로 압축한 섬유판","more":"강화마루 바탕재. 수분을 흡수하면 팽창, 변형."},{"ko":"래핑 몰딩","en":"","say":"MDF, 파티클 보드 표면에 무늬목이나 인조 시트를 씌운 몰딩","more":"짝은 원목 몰딩. 위치별 : 천장 몰딩, 걸레받이, 허리몰딩."}],"slides":[{"kind":"title","big":"나무 바닥 네 가지","sub":"강화는 끼우고, 강은 붙인다"},{"kind":"goal","items":["마루 네 가지를 가격 순서로 말해요","강화마루와 강마루의 바탕재와 시공법을 구별해요","몰딩 종류와 위치 이름을 말해요"]},{"kind":"analogy","head":"퍼즐과 스티커","scene":"퍼즐은 조각끼리 끼워 바닥에 올려놓고, 스티커는 바닥에 꾹 붙여요.","map":[["끼워 올려놓는 퍼즐","**강화마루**"],["바닥에 붙이는 스티커","**강마루**"],["퍼즐 판의 재료","**HDF**"]]},{"kind":"figure","head":"가격 계단","svg":"<svg viewBox=\"0 0 480 275\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"50\" y=\"170\" width=\"80\" height=\"50\" rx=\"2\" class=\"n b1\"/><text x=\"90.0\" y=\"162.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">저가<\/text><text x=\"90.0\" y=\"245.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">강화마루<\/text><rect x=\"160\" y=\"130\" width=\"80\" height=\"90\" rx=\"2\" class=\"n3 b2\"/><text x=\"200.0\" y=\"122.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">중가<\/text><text x=\"200.0\" y=\"245.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">강마루<\/text><rect x=\"270\" y=\"90\" width=\"80\" height=\"130\" rx=\"2\" class=\"n2 b3\"/><text x=\"310.0\" y=\"82.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">중/고가<\/text><text x=\"310.0\" y=\"245.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">합판마루<\/text><rect x=\"380\" y=\"50\" width=\"80\" height=\"170\" rx=\"2\" class=\"n2 b4\"/><text x=\"420.0\" y=\"42.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">고가<\/text><text x=\"420.0\" y=\"245.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b4\">원목마루<\/text><text x=\"240.0\" y=\"266.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">강화마루만 비접착식, 나머지 셋은 접착식이에요<\/text><\/svg>","caption":"강화, 강, 합판, 원목 순으로 비싸지고 진짜 나무에 가까워져요.","builds":4},{"kind":"compare","head":"마루 네 가지 비교","cols":["마루","바탕과 표면","시공","가격"],"rows":[["**강화마루**","HDF 위 표면장식지","비접착식","저가"],["**강마루**","합판 위 표면장식지","접착식","중가"],["**합판마루**","합판 위 얇은 무늬목, 2mm 이하","접착식","중/고가"],["**원목마루**","합판 위 두꺼운 무늬목, 2mm 이상","접착식","고가"]]},{"kind":"points","head":"**원목마루**","items":["통원목 제품이나 **합판(Plywood)** 위에 두꺼운 천연 원목 단판을 붙인 제품이에요","표면이 두꺼워 샌딩 후 재도장이 가능하고 정전기가 없어요","가격이 높고 습기와 온도 변화에 약해 관리가 어려워요"]},{"kind":"points","head":"**합판마루** (온돌마루)","items":["온돌 난방에서 원목의 수축, 팽창과 뒤틀림을 줄이려고 개발됐어요","**합판(Plywood)** 바탕재 위에 천연 **무늬목(Wood Veneer)** 을 붙이고 도장해요","치수 안정성이 높고 바닥난방에 적합하지만 긁힘에 약해요"]},{"kind":"points","head":"**강화마루**","items":["**HDF** 바탕재 위에 장식층과 내마모 표면층을 쌓아요","접착제 없이 홈을 결합하는 클릭 방식이에요, 본드 시공 안 함!","바닥에 붙이지 않는 현가식이라 바탕면 평활도가 중요해요","마루와 걸레받이 사이는 수축현상 때문에 실리콘 처리를 안 해요"]},{"kind":"compare","head":"**강화마루** 장단점","cols":["장점","단점"],"rows":[["내마모, 내긁힘 우수","자연스러운 질감이 떨어져요"],["가격이 경제적","**HDF** 가 수분을 먹으면 팽창, 변형"],["시공과 철거가 간편","보행 시 소리, 연마 재마감 어려움"]]},{"kind":"points","head":"**강마루**","items":["**합판(Plywood)** 바탕재 위에 인쇄한 장식층과 표면층을 쌓아요","바닥에 본드로 직접 붙이는 접착식이에요, 본드 시공!","들뜸과 울림이 적고 온돌 열전달에 유리해요, 아파트 등 주거에 많이 써요","대신 철거와 부분 교체가 어려워요"]},{"kind":"compare","head":"층 구성 그림","cols":["마루","위에서 아래로"],"rows":[["**강화마루**","오버레이지, 무늬 장식지, HDF 섬유판, 후면지"],["**강마루**","오버레이지, 무늬 장식지, 기재층, 합판"]]},{"kind":"points","head":"몰딩재","items":["몰딩은 벽, 천장, 문, 가구의 경계나 이음부를 마감하는 띠 모양 부재예요","종류는 원목 몰딩, **래핑 몰딩**, 석고, 우레탄, 플라스틱 제품이에요","**래핑 몰딩** 은 MDF, 파티클 보드에 무늬목이나 인조 시트를 씌운 거예요"]},{"kind":"compare","head":"위치로 부르는 이름","cols":["위치","이름"],"rows":[["내벽과 천장이 만나는 곳","천장 몰딩"],["바닥과 벽이 만나는 곳","걸레받이"],["벽 중간 부분","허리몰딩"]]},{"kind":"check","q":"HDF 를 바탕재로 하고 클릭 방식으로 시공하는 마루는?","choices":["강화마루","강마루","원목마루"],"a":0,"why":"강마루는 합판 바탕을 본드로 붙여요."},{"kind":"check","q":"MDF 위에 무늬목이나 인조 시트를 씌운 몰딩은?","choices":["원목 몰딩","래핑 몰딩","석고 몰딩"],"a":1,"why":"래핑 몰딩은 MDF, 파티클 보드 표면을 감싸 마감한 몰딩이에요."},{"kind":"warn","head":"이름이 비슷한 짝","items":["**강화마루** 는 HDF + 끼우기, **강마루** 는 합판 + 본드예요","**합판마루** 와 **원목마루** 는 무늬목 두께 2mm 로 갈라요","실리콘을 안 하는 곳은 강화마루와 걸레받이 사이예요"]},{"kind":"english","head":"답안에 쓸 문장","en":"강화마루는 HDF 바탕에 클릭 방식으로 끼우는 비접착식이고, 강마루는 합판 바탕을 본드로 붙이는 접착식이다.","ko":"바탕재와 시공법을 짝으로 써요"},{"kind":"recap","items":["가격은 **강화마루**, **강마루**, **합판마루**, **원목마루** 순으로 올라요","**강화마루** 는 **HDF**, 클릭, 현가식, 실리콘 안 함이에요","**강마루** 는 합판, 본드, 들뜸 적음, 철거 어려움이에요","몰딩은 원목, **래핑 몰딩**, 기타, 위치는 천장 몰딩, 걸레받이, 허리몰딩이에요","오늘의 용어: 원목마루, 합판마루, 강화마루, 강마루, HDF, 래핑 몰딩"]}]},{"id":"w4-8","title":"목공구","goal":"목공구를 측정 및 기준, 절삭, 기타 세 묶음으로 나누고 이름과 쓰임을 짝지을 수 있어요","terms":[{"ko":"먹통","en":"","say":"먹매김할 때 쓰는 목수의 가장 기본 휴대 장비","more":"목재 재단 면 표시, 바닥, 벽, 천장에 자리 표시."},{"ko":"줄 톱","en":"Jig saw","say":"지그재그로 직선, 원형을 자르거나 모양을 따내는 톱","more":"직소기라고도 함. 지그재그로 자를 수 있다는 기능에서 생긴 이름."},{"ko":"서클 커터","en":"","say":"드릴에 꽂아 원형 구멍을 뚫는 공구","more":"천장 등구멍 타공에 많이 씀."},{"ko":"컴프레셔","en":"","say":"공기압 공구를 돌리는 공기압축기","more":"타카, 에어 스프레이, 에어드릴에 필수."},{"ko":"타카","en":"","say":"공기압으로 핀을 박아 판재를 고정하는 공구","more":"핀은 일 자 핀과 ㄷ 자 핀. 천장 2겹째 석고보드에 ㄷ 자 타카 핀."}],"slides":[{"kind":"title","big":"목수의 연장통","sub":"재고, 자르고, 박는 세 묶음"},{"kind":"goal","items":["목공구를 측정, 절삭, 기타 세 묶음으로 나눠요","공구 이름과 쓰임을 짝지어요","타카 핀 두 가지를 말해요"]},{"kind":"analogy","head":"요리사의 도구","scene":"요리사는 계량컵으로 재고, 칼로 자르고, 가스레인지로 익혀요.","map":[["계량컵과 저울","측정 및 기준 도구, **먹통**"],["칼","절삭 도구, **줄 톱(Jig saw)**"],["가스레인지","기타 도구, **컴프레셔**"]]},{"kind":"figure","head":"목공구 세 묶음","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"10\" y=\"40\" width=\"146\" height=\"170\" rx=\"2\" class=\"box2 b1\"/><text x=\"83.0\" y=\"93.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">측정 및 기준<\/text><text x=\"83.0\" y=\"112.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">레벨기<\/text><text x=\"83.0\" y=\"131.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">줄자<\/text><text x=\"83.0\" y=\"150.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">직각 스틸자<\/text><text x=\"83.0\" y=\"169.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">먹통<\/text><rect x=\"167\" y=\"40\" width=\"146\" height=\"170\" rx=\"2\" class=\"box b2\"/><text x=\"240.0\" y=\"93.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b2\">절삭<\/text><text x=\"240.0\" y=\"112.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">톱, 띠 톱, 줄 톱<\/text><text x=\"240.0\" y=\"131.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">대패, 끌<\/text><text x=\"240.0\" y=\"150.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">서클 커터<\/text><text x=\"240.0\" y=\"169.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">루터기<\/text><rect x=\"324\" y=\"40\" width=\"146\" height=\"170\" rx=\"2\" class=\"box b3\"/><text x=\"397.0\" y=\"102.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b3\">기타<\/text><text x=\"397.0\" y=\"122.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">컴프레셔<\/text><text x=\"397.0\" y=\"140.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">전동 드릴<\/text><text x=\"397.0\" y=\"160.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">타카<\/text><text x=\"240.0\" y=\"245.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b3\">재고, 자르고, 박아요<\/text><\/svg>","caption":"측정 및 기준 도구, 절삭 도구, 기타 도구 세 묶음이에요.","builds":3},{"kind":"compare","head":"측정 및 기준 도구","cols":["공구","쓰임"],"rows":[["수평, 수직 레벨기","기포로 수평과 수직, 요즘은 레이저 레벨기"],["경사 측정기","경사면의 각도, 구배 설정"],["줄자","2m 에서 100m 까지, 먼 거리는 레이저 측정기"],["직각 스틸자","직각을 재는 목수의 기본 공구"],["**먹통**","재단 면 표시, 바닥, 벽, 천장 자리 표시"]]},{"kind":"points","head":"**먹통**","items":["**먹통** 은 목수들이 가장 기본적으로 휴대하는 장비예요","2강에서 배운 **먹매김** 에 써요","4-9 의 목재 벽체도 **먹매김** 으로 시작해요"]},{"kind":"compare","head":"절삭 도구 (1) 톱","cols":["공구","쓰임"],"rows":[["톱","부분적 정밀가공"],["전기 톱","원형 톱날, 작업대에 고정, 2인 1조"],["띠 톱","고리 모양 띠 톱날을 고속 회전"],["**줄 톱(Jig saw)**","지그재그로 직선, 원형, 모양 따내기"],["각도커팅기","여러 각도, 같은 규격 반복 절단"]]},{"kind":"compare","head":"절삭 도구 (2) 깎고 뚫기","cols":["공구","쓰임"],"rows":[["대패","끝마무리, 표면 다듬기, 막대패, 중간대패, 다듬질대패"],["전동 대패","회전 날로 표면을 평활하게"],["끌","구멍파기용과 깎기용, 자루 머리 링으로 구분"],["**서클 커터**","드릴에 꽂아 원형 구멍, 천장 등구멍"],["루터기","가장자리 무늬, 홈, 경첩자리 홈"]]},{"kind":"compare","head":"기타 도구","cols":["공구","쓰임"],"rows":[["**컴프레셔**","공기압축기, 공기압 공구에 필수"],["전동 드릴","구멍 뚫기, 나사못 박기, 목재용, 콘크리트용, 철재용 날"],["**타카**","공기압으로 **합판(Plywood)**, 석고보드, 각재, MDF 고정"]]},{"kind":"points","head":"**타카** 와 핀","items":["**타카** 는 **컴프레셔** 의 공기압으로 핀을 박아요","핀은 일 자 핀과 ㄷ 자 핀이 있고 길이도 다양해요","ㄷ 자 **타카** 핀은 4-9 천장 2겹째 석고보드에서 다시 나와요"]},{"kind":"check","q":"드릴에 꽂아 천장 등구멍을 타공하는 공구는?","choices":["서클 커터","줄 톱","루터기"],"a":0,"why":"줄 톱은 모양 따내기, 루터기는 홈과 무늬예요."},{"kind":"check","q":"타카를 쓰려면 꼭 있어야 하는 공기압축기는?","choices":["전동 드릴","컴프레셔","각도커팅기"],"a":1,"why":"컴프레셔가 타카, 에어 스프레이, 에어드릴을 돌려요."},{"kind":"warn","head":"헷갈리는 짝","items":["**줄 톱(Jig saw)** 은 지그재그로 모양 따내기, 띠 톱은 고리 모양 톱날이에요","**서클 커터** 는 원형 구멍, 루터기는 홈과 무늬예요","전기 톱은 작업대에 고정해 2인 1조로 작업해요"]},{"kind":"recap","items":["측정 및 기준 도구의 기본은 직각 스틸자와 **먹통** 이에요","**줄 톱(Jig saw)** 은 직소기, 지그재그로 모양을 따내요","**서클 커터** 는 천장 등구멍, 루터기는 홈이에요","**컴프레셔** 가 **타카** 를 돌리고 핀은 일 자와 ㄷ 자예요","오늘의 용어: 먹통, 줄 톱(Jig saw), 서클 커터, 컴프레셔, 타카"]}]},{"id":"w4-9","title":"목공사 시공: 벽체, 천장, 무늬목, 마루","goal":"목재 벽체 순서와 취부 규칙, 문틀, 목재 천장, 무늬목 붙이기와 마루 깔기 요령을 말할 수 있어요","terms":[{"ko":"세로 목","en":"","say":"목재 벽체 틀에서 하부, 상부 고정목 사이에 세우는 세로 부재","more":"간격 300, 450, 600mm 모듈. 필요하면 가로 보강목."},{"ko":"일면 벽체","en":"","say":"기존 벽 앞에 한 겹 틀을 세워 한쪽 면만 마감하는 벽","more":"기존 벽 마감, 설비 공간 확보. 짝은 양면 벽체(공간 구획용 독립 벽)."},{"ko":"취부","en":"","say":"석고보드, 합판 등을 붙이는 것을 부르는 현장 용어","more":"벽은 9.5mm 2겹(2 플라이 치기). 1겹째 나사못, 2겹째 본드 + 나사못, 이음매 어긋나게."},{"ko":"문선","en":"","say":"문틀 주위 마감이 끝난 뒤 덧붙이는 테두리 마감재","more":"문틀 : X 자 먹매김, 수직, 반드시 보강, 마감 후 문선."},{"ko":"반자틀","en":"","say":"나무 천장에서 보드를 붙이는 바탕 목틀","more":"소규모 공사용. 각재 간격 300 또는 450mm. 위로 반자틀받이, 달대, 달대받이."},{"ko":"스프렁 플로어","en":"Sprung Floor","say":"멍에와 장선으로 바닥을 띄운 체육관 탄성바닥 마루","more":"충격 완화와 탄성 확보. 요즘은 금속 시스템 제품."},{"ko":"셀프레벨링","en":"","say":"유동성 높은 모르타르를 부어 스스로 퍼지게 해 바닥 수평을 맞추는 공법","more":"자동수평몰탈. 미장면이 평활하지 못하면 3mm 합판을 붙이기도 함."}],"slides":[{"kind":"title","big":"나무로 벽, 천장, 바닥","sub":"3강의 순서를 나무로 다시 해요"},{"kind":"goal","items":["목재 벽체 시공 순서를 말해요","보드 취부 규칙과 문틀 세우기를 말해요","목재 천장과 시스템 천장을 비교해요","무늬목 붙이기와 마루 깔기 요령을 말해요"]},{"kind":"analogy","head":"뼈대에 살 붙이기","scene":"3강 건식벽체처럼 나무 뼈대를 세우고 보드라는 살을 붙여요.","map":[["뼈","**각재** 로 짠 **세로 목**"],["살","석고보드, 합판"],["살 붙이기","**취부**"]]},{"kind":"steps","head":"목재 벽체 순서","steps":["먹매김을 하고 각재를 양중해요, 함수율과 휨 정도를 확인해요","하부, 상부 고정목을 대고 **세로 목** 을 세워요","보드를 **취부** 해요, 양면 벽은 한쪽, 단열재, 반대쪽 순서예요","문틀을 세우고 보강해요","몰딩, 조인트 테이프와 퍼티로 마감해요"],"answer":"먹매김, 틀, 보드, 문틀, 마감 순서예요"},{"kind":"figure","head":"목재 벽체 틀","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"60\" y=\"40\" width=\"260\" height=\"12\" rx=\"2\" class=\"n2 b1\"/><rect x=\"60\" y=\"208\" width=\"260\" height=\"12\" rx=\"2\" class=\"n2 b1\"/><text x=\"190.0\" y=\"30.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">상부 고정목<\/text><text x=\"190.0\" y=\"246.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">하부 고정목<\/text><rect x=\"70\" y=\"52\" width=\"12\" height=\"156\" rx=\"2\" class=\"n b2\"/><rect x=\"140\" y=\"52\" width=\"12\" height=\"156\" rx=\"2\" class=\"n b2\"/><rect x=\"210\" y=\"52\" width=\"12\" height=\"156\" rx=\"2\" class=\"n b2\"/><rect x=\"280\" y=\"52\" width=\"12\" height=\"156\" rx=\"2\" class=\"n b2\"/><text x=\"335.0\" y=\"110.0\" font-size=\"15\" text-anchor=\"start\" class=\"tb b3\">세로 목<\/text><text x=\"335.0\" y=\"136.0\" font-size=\"14\" text-anchor=\"start\" class=\"tm b3\">300, 450, 600mm<\/text><text x=\"335.0\" y=\"164.0\" font-size=\"14\" text-anchor=\"start\" class=\"tm b3\">보드를 취부해요<\/text><\/svg>","caption":"고정목 사이에 세로 목을 300, 450, 600mm 모듈로 세우고 보드를 붙여요.","builds":3},{"kind":"points","head":"틀 짜기 규칙","items":["**세로 목** 간격은 300, 450, 600mm 모듈이고 필요하면 가로 보강목을 넣어요","휨, 비틀림, 심한 옹이가 있는 자재는 빼요","바탕에 따라 타정핀, 콘크리트용 피스, 앵커로 고정해요"]},{"kind":"compare","head":"벽체 두 가지","cols":["벽체","특징"],"rows":[["**일면 벽체**","기존 벽 앞에 한 겹 틀, 한쪽 면만 마감, 설비 공간 확보"],["양면 벽체","공간 구획용 독립 벽, 양쪽 면에 부착"]]},{"kind":"points","head":"**취부** 규칙","items":["벽면은 방화구역, 피트, 엘리베이터 피트를 빼면 9.5mm 2겹, 2 플라이 치기예요","1겹째는 나사못, 2겹째는 배면에 본드를 바르고 나사못이에요","이음매는 1겹째와 2겹째를 어긋나게, 모서리는 코너비드예요"]},{"kind":"points","head":"문틀 세우기","items":["문틀 자리에 X 자로 먹매김하고 수직을 정확히 맞춰요","개폐 충격을 흡수하도록 반드시 보강해요","기본 마감이 끝나면 **문선** 을 덧붙여요","**멤브레인** 은 MDF 에 필름, ABS 는 합성수지 문짝이에요"]},{"kind":"compare","head":"목재 천장과 시스템 천장","cols":["구분","목재 천장","시스템 천장"],"rows":[["매달기","달대받이, 달대","달대 볼트, 행거 세트"],["뼈대","반자틀받이, **반자틀**","캐링 채널, **M-Bar**"],["쓰는 곳","소규모 공사","3강에서 본 경량 천장"]]},{"kind":"points","head":"**반자틀** 천장 숫자","items":["각재 간격은 300mm 또는 450mm 예요","석고보드 9.5mm 2겹, 1겹째 나사못, 2겹째 본드 + 나사못이나 ㄷ 자 타카 핀이에요","퍼티 후 등 구멍 먹매김, 쥐톱이나 서클커터로 타공해요"]},{"kind":"steps","head":"**무늬목(Wood Veneer)** 붙이기","steps":["물에 적시고 길이, 폭을 재단해요","롤러로 본드를 바르고 한쪽부터 붙여요","2장 이상이면 한 번 바로, 한 번 뒤집어 무늬를 이어요","헤라로 압착하고 겹친 부분 중앙을 칼질해요","본드와 수분을 닦고 그늘에서 말려요","다림질 후 마감 칠을 해요"],"answer":"햇볕이 아니라 그늘에서 말려요"},{"kind":"points","head":"현장 **무늬목(Wood Veneer)** 작업 (중요!)","items":["현장은 공장보다 여건이 나빠 품질이 많이 떨어져요","작업공간을 최대한 깨끗하게 유지하고 바탕면 먼지를 없애요","MDF 패널은 무늬가 끊기지 않게 결을 연속으로 맞춰요","마감 후 투명 락커 도장으로 먼지를 막아요"]},{"kind":"points","head":"마루 깔기","items":["**스프렁 플로어(Sprung Floor)** 는 멍에와 장선을 먼저 시공해 바닥을 띄워요","띄우는 이유는 충격 완화와 탄성 확보예요","모르타르 바닥이 고르지 않으면 **셀프레벨링** 으로 편평하게 해요","미장면이 평활하지 못하면 3mm 합판을 붙이고 쪽마루를 붙여요"]},{"kind":"check","q":"석고보드, 합판 등을 붙이는 것을 현장에서 부르는 말은?","choices":["취부","양중","문선"],"a":0,"why":"양중은 자재를 쓸 자리로 올리는 일, 문선은 문틀 주위 마감재예요."},{"kind":"check","q":"체육관 바닥처럼 멍에와 장선으로 바닥을 띄우는 마루는?","choices":["셀프레벨링","스프렁 플로어","일면 벽체"],"a":1,"why":"셀프레벨링은 모르타르로 바닥 수평을 맞추는 공법이에요."},{"kind":"warn","head":"함정","items":["1겹째는 나사못만, 2겹째는 본드 + 나사못이에요","무늬목은 햇볕이 아니라 그늘에서 말려요","**반자틀** 천장은 대규모 공사에는 거의 쓰지 않아요"]},{"kind":"recap","items":["벽은 먹매김, 고정목과 **세로 목**, **취부**, 문틀, 마감 순서예요","**일면 벽체** 는 기존 벽 앞 한 겹, 보드는 9.5mm 2겹이에요","문틀은 반드시 보강하고 마감 후 **문선** 을 덧붙여요","**반자틀** 천장은 소규모, 각재 간격 300 또는 450mm 예요","**스프렁 플로어(Sprung Floor)** 는 탄성, **셀프레벨링** 은 바닥 수평이에요","오늘의 용어: 세로 목, 일면 벽체, 취부, 문선, 반자틀, 스프렁 플로어(Sprung Floor), 셀프레벨링"]}]},{"id":"w4-10","title":"[실습] 마루 바닥 상세도와 목문 상세도","goal":"온돌 없는 바닥과 온돌 바닥의 층 순서와 두께, 목문 상세도의 벽 두께와 문짝 구성을 말할 수 있어요","terms":[{"ko":"엑셀 파이프","en":"","say":"온돌 바닥 모르타르 속에 넣는 온수난방용 관","more":"Ø15mm @200, 고정핀으로 고정. 아래층은 경량 기포 콘크리트 60~100, 비드법 발포 폴리스틸렌 20~30."},{"ko":"허니콤 보드","en":"","say":"두꺼운 종이를 벌집 모양으로 가공한 문짝 심재","more":"테두리 PVC 심재, 겉면 ABS 수지판과 필름 = ABS 도어. 습기에 강하고 가벼움."},{"ko":"멤브레인","en":"","say":"겉면이 MDF이고 그 위에 필름을 붙인 문짝","more":"입체 디자인 가능. 짝은 ABS 문짝(합성수지, 습기에 강함, 입체 어려움)."},{"ko":"원목마루","en":"","say":"통원목이나 두꺼운 원목 단판을 쓴 가장 비싼 마루","more":"샌딩 후 재도장 가능, 정전기 없음. 습기와 온도 변화에 약함. 합판 위 무늬목 2mm 이상."}],"slides":[{"kind":"title","big":"바닥과 문을 잘라 보기","sub":"층마다 재료와 두께를 읽어요"},{"kind":"goal","items":["온돌 없는 바닥과 온돌 바닥의 층 순서를 말해요","층마다 두께 숫자를 외워요","목문 상세도의 벽 두께와 문짝 구성을 읽어요"]},{"kind":"analogy","head":"케이크 단면","scene":"케이크를 잘라 보면 빵, 크림, 과일 층이 보여요. 상세도는 바닥을 자른 단면이에요.","map":[["맨 위 장식","**원목마루** THK 12mm"],["크림 속 과일","모르타르 속 **엑셀 파이프**"],["맨 아래 받침","기존 SLAB"]]},{"kind":"compare","head":"온돌 없는 바닥 (상업, 오피스)","cols":["층 (위에서 아래로)","표기"],"rows":[["마감","**원목마루** THK 12MM"],["접착","마루 접착제, 보통 3MM 이상 두께층"],["평탄화","THK 50~60MM 시멘트 모르타르"],["구조체","기존 SLAB (건축)"]]},{"kind":"figure","head":"온돌 바닥 단면","svg":"<svg viewBox=\"0 0 480 250\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"60\" y=\"195\" width=\"240\" height=\"40\" rx=\"2\" class=\"n4 b1\"/><text x=\"310.0\" y=\"220.0\" font-size=\"14\" text-anchor=\"start\" class=\"tb b1\">기존 SLAB<\/text><rect x=\"60\" y=\"170\" width=\"240\" height=\"25\" rx=\"2\" class=\"box b2\"/><text x=\"310.0\" y=\"187.0\" font-size=\"14\" text-anchor=\"start\" class=\"t b2\">비드법 20~30<\/text><rect x=\"60\" y=\"110\" width=\"240\" height=\"60\" rx=\"2\" class=\"n3 b3\"/><text x=\"310.0\" y=\"145.0\" font-size=\"14\" text-anchor=\"start\" class=\"t b3\">기포 콘크리트 60~100<\/text><rect x=\"60\" y=\"60\" width=\"240\" height=\"50\" rx=\"2\" class=\"n b4\"/><text x=\"310.0\" y=\"92.0\" font-size=\"14\" text-anchor=\"start\" class=\"t b4\">모르타르 50~60<\/text><text x=\"180.0\" y=\"86.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b4\">엑셀 파이프 Ø15 @200<\/text><circle cx=\"90.0\" cy=\"100.0\" r=\"4\" class=\"n2 b4\"/><circle cx=\"130.0\" cy=\"100.0\" r=\"4\" class=\"n2 b4\"/><circle cx=\"170.0\" cy=\"100.0\" r=\"4\" class=\"n2 b4\"/><circle cx=\"210.0\" cy=\"100.0\" r=\"4\" class=\"n2 b4\"/><circle cx=\"250.0\" cy=\"100.0\" r=\"4\" class=\"n2 b4\"/><rect x=\"60\" y=\"54\" width=\"240\" height=\"6\" rx=\"2\" class=\"box b5\"/><text x=\"310.0\" y=\"66.0\" font-size=\"14\" text-anchor=\"start\" class=\"t b5\">마루 접착제 3 이상<\/text><rect x=\"60\" y=\"40\" width=\"240\" height=\"14\" rx=\"2\" class=\"n2 b5\"/><text x=\"310.0\" y=\"44.0\" font-size=\"14\" text-anchor=\"start\" class=\"tb b5\">원목마루 THK 12<\/text><\/svg>","caption":"아래부터 SLAB, 비드법, 기포 콘크리트, 모르타르(엑셀 파이프), 접착제, 원목마루예요.","builds":5},{"kind":"compare","head":"온돌 바닥 (주거)","cols":["층 (위에서 아래로)","표기"],"rows":[["마감, 접착","원목마루 THK 12MM, 마루 접착제"],["난방층","THK 50~60MM 모르타르, 엑셀 파이프 Ø15MM @200"],["경량층","THK 60~100MM 경량 기포 콘크리트"],["단열, 완충층","THK 20~30MM 비드법 발포 폴리스틸렌"],["구조체","기존 SLAB (건축)"]]},{"kind":"points","head":"왜 층이 늘어날까","items":["주거 공간은 층간소음을 줄이고 바닥 난방을 하려고 층을 더해요","**엑셀 파이프** 는 온수난방용 관이고 고정핀으로 고정해요","**원목마루** 폭은 90~120 이에요, THK 는 두께라는 뜻이에요"]},{"kind":"steps","head":"온돌 바닥 아래부터 쌓기","steps":["기존 SLAB","비드법 발포 폴리스틸렌 20~30","경량 기포 콘크리트 60~100","시멘트 모르타르 50~60, 속에 **엑셀 파이프**","마루 접착제 3 이상","**원목마루** 12"],"answer":"비드법, 기포, 모르타르 속 엑셀, 본드, 마루 순서예요"},{"kind":"compare","head":"목문 상세도 표기","cols":["부위","표기"],"rows":[["벽체","9.5MM 석고보드 2PLY, C-STUD 65T, 50MM INSULATION"],["문틀","45X100 라왕 문틀, 주변 9MM MDF 보강"],["문짝 테두리","45X40 라왕 집성목"],["문짝 면","20X40 각재, 5MM 라왕 **합판(Plywood)** 2PLY, 컬러 락카"]]},{"kind":"steps","head":"벽 두께 103 계산","steps":["한쪽 보드 두 장은 9.5 + 9.5 = 19 예요","스터드는 65 예요","반대쪽도 19 예요","19 + 65 + 19 를 더해요"],"answer":"103mm, 3강의 경량 벽체와 같은 두께예요","given":"C-STUD 65T, 9.5mm 석고보드 양면 2PLY"},{"kind":"points","head":"폭과 높이 숫자","items":["폭은 전체 900 = 40 + 820 + 40 으로 적혀 있어요","아래쪽 치수는 35 + 10 + 810 + 10 + 35 = 900 이에요","문짝 두께 45, 입면 높이 2,100 과 2,060, 손잡이 900~1,000 이에요"]},{"kind":"compare","head":"요즘 문짝","cols":["문짝","구성"],"rows":[["ABS 도어","**허니콤 보드** 심재, PVC 심재 테두리, ABS 수지판, 필름 마감"],["**멤브레인** 도어","겉면 MDF 판재에 필름을 붙여요"]]},{"kind":"points","head":"**허니콤 보드** 가 늘어난 까닭","items":["두꺼운 종이를 벌집 모양으로 가공해 심재로 넣어요","습기에 강하고 변형이 적으며 목재도어보다 가벼워요","4-9 의 **멤브레인** 과 ABS 문짝 짝을 다시 떠올려요"]},{"kind":"check","q":"온돌 바닥에서 엑셀 파이프가 들어가는 층은?","choices":["비드법 발포 폴리스틸렌","시멘트 모르타르","경량 기포 콘크리트"],"a":1,"why":"THK 50~60MM 시멘트 모르타르 속에 Ø15MM 를 @200 으로 고정해요."},{"kind":"check","q":"요즘 ABS 도어의 심재로 넣는 벌집 모양 종이는?","choices":["허니콤 보드","코아 합판","OSB"],"a":0,"why":"허니콤 보드를 넣고 테두리는 PVC 심재로 마무리해요."},{"kind":"warn","head":"헷갈리는 점","items":["비드법이 아래, 경량 기포 콘크리트가 위예요, 순서를 바꾸지 않아요","온돌 없는 바닥에는 비드법, 기포 콘크리트, 엑셀 배관이 없어요","103 은 새로 세운 양면 벽이고 3강의 덧붙이는 벽 84 와 달라요"]},{"kind":"recap","items":["온돌 없는 바닥은 SLAB, 모르타르, 접착제, **원목마루** 예요","온돌 바닥은 비드법, 기포 콘크리트, 모르타르 속 **엑셀 파이프** 가 더해져요","목문 벽 두께는 103, 폭은 40 + 820 + 40 = 900 이에요","문틀과 문짝 테두리는 라왕, 즉 **나왕(lauan)** 이에요","ABS 도어 속은 **허니콤 보드**, **멤브레인** 은 MDF 에 필름이에요","오늘의 용어: 엑셀 파이프, 허니콤 보드, 멤브레인, 원목마루"]}]}]};
